// -----------------------------------------
// Helpers: make SVG ids unique per instance
// -----------------------------------------

const rewriteRefValue = (value: unknown, prefix: string): unknown => {
  if (typeof value !== 'string') return value;

  var out = value;

  // url(#...)
  out = out.replace(/url[(]#([^)]+)[)]/g, function (_m, id) {
    return 'url(#' + prefix + id + ')';
  });

  // "#id" refs (href/xlinkHref) - but NOT hex colors
  // Hex colors: #RGB or #RRGGBB or #RRGGBBAA (3, 6, or 8 hex digits)
  if (out.charAt(0) === '#' && out.length > 1) {
    var rest = out.slice(1);
    var isHexColor = /^[0-9A-Fa-f]{3}$|^[0-9A-Fa-f]{6}$|^[0-9A-Fa-f]{8}$/.test(rest);
    if (!isHexColor) {
      out = '#' + prefix + rest;
    }
  }

  return out;
};

const prefixSvgIds = (node: React.ReactNode, prefix: string): React.ReactNode => {
  if (!React.isValidElement(node)) return node;

  var el = node as React.ReactElement;
  var props: Record<string, unknown> = Object.assign({}, el.props);

  if (typeof props.id === 'string') {
    props.id = prefix + props.id;
  }

  var refKeys = ['fill', 'stroke', 'filter', 'clipPath', 'mask', 'href', 'xlinkHref'];
  for (var i = 0; i < refKeys.length; i++) {
    var k = refKeys[i];
    if (k in props) {
      props[k] = rewriteRefValue(props[k], prefix);
    }
  }

  var children = props.children;
  if (children !== undefined && children !== null) {
    props.children = React.Children.map(
      children as React.ReactElement,
      function (c: React.ReactElement) {
        return prefixSvgIds(c, prefix);
      }
    );
  }

  return React.cloneElement(el, props);
};

const makeSafePrefix = (name: string, rid: string): string => {
  var safe = rid.replace(/[^a-zA-Z0-9_]/g, '_');
  return name + '__' + safe + '__';
};

const parseViewBox = (vb: string): { w: number; h: number } => {
  var parts = vb.trim().split(/\s+/).map(function (x) { return Number(x); });
  if (parts.length === 4 && isFinite(parts[2]) && isFinite(parts[3]) && parts[2] > 0 && parts[3] > 0) {
    return { w: parts[2], h: parts[3] };
  }
  return { w: 24, h: 24 };
};

const toNumberIfPossible = (v: number | string | undefined): number | null => {
  if (v === undefined) return null;
  if (typeof v === 'number') return isFinite(v) ? v : null;
  var n = Number(v);
  return isFinite(n) ? n : null;
};

export const Icon: React.FC<IconProps> = function ({
  name,
  variant = 'solid',
  size = 24,
  width,
  height,
  color,
  colorSecondary,
  gradientType = 'linear',
  gradientDirection = 'vertical',
  gradientAngle = 0,
  gradientRadius = 50,
  colorFirst = '#8b5cf6',
  colorSecond = '#ec4899',
  offsetFirst = '0%',
  offsetSecond = '100%',
  shadow = false,
  shadowColor = '#000000',
  shadowBlur = 4,
  shadowOffsetX = 0,
  shadowOffsetY = 2,
  shadowOpacity = 0.3,
  fit = 'contain',
  ...props
}) {
  // All hooks must be called before any early returns
  var reactId = React.useId();
  var prefix = React.useMemo(function () {
    return makeSafePrefix(name, reactId);
  }, [name, reactId]);

  var item = (
    icons as Record<
      string,
      {
        viewBox: string;
        solid: React.ReactNode;
        gradient?: React.ReactNode;
        original?: React.ReactNode;
        duotone?: React.ReactNode;
      }
    >
  )[name];

  var vb = parseViewBox(item?.viewBox ?? '0 0 24 24');
  var ratio = vb.h / vb.w;

  var wNum = toNumberIfPossible(width);
  var hNum = toNumberIfPossible(height);
  var sNum = toNumberIfPossible(size);

  var wOut: number | string = size ?? 24;
  var hOut: number | string = size ?? 24;

  if (wNum !== null && hNum !== null) {
    wOut = width ?? 24;
    hOut = height ?? 24;
  } else if (wNum !== null) {
    wOut = width ?? 24;
    hOut = wNum * ratio;
  } else if (hNum !== null) {
    hOut = height ?? 24;
    wOut = hNum / ratio;
  } else if (sNum !== null) {
    wOut = size ?? 24;
    hOut = sNum * ratio;
  } else {
    wOut = size ?? 24;
    hOut = size ?? 24;
  }

  // For dynamic gradient, use solid variant (which has currentColor)
  var raw =
    variant === 'original' && item?.original
      ? item.original
      : variant === 'duotone' && item?.duotone
      ? item.duotone
      : item?.solid ?? null;

  var content = React.useMemo(function () {
    return raw ? prefixSvgIds(raw, prefix) : null;
  }, [raw, prefix]);

  // --- Dynamic gradient and shadow ---
  var gradientId = prefix + 'dynamic-gradient';
  var shadowId = prefix + 'shadow-filter';
  var shouldUseGradient = variant === 'gradient';

  // Replace secondary color variable for duotone
  var contentWithSecondaryColor = React.useMemo(
    function () {
      if (variant !== 'duotone' || !colorSecondary) return content;

      var replaceSecondaryColor = (node: React.ReactNode): React.ReactNode => {
        if (!React.isValidElement(node)) return node;

        var el = node as React.ReactElement;
        var elementProps: Record<string, unknown> = Object.assign({}, el.props);

        // Replace fill with var(--icon-secondary-color, ...) pattern
        if (
          typeof elementProps.fill === 'string' &&
          elementProps.fill.startsWith('var(--icon-secondary-color')
        ) {
          elementProps.fill = colorSecondary;
        }

        // Replace stroke with var(--icon-secondary-color, ...) pattern
        if (
          typeof elementProps.stroke === 'string' &&
          elementProps.stroke.startsWith('var(--icon-secondary-color')
        ) {
          elementProps.stroke = colorSecondary;
        }

        var children = elementProps.children;
        if (children !== undefined && children !== null) {
          elementProps.children = React.Children.map(
            children as React.ReactElement,
            function (c: React.ReactElement) {
              return replaceSecondaryColor(c);
            }
          );
        }

        return React.cloneElement(el, elementProps);
      };

      return replaceSecondaryColor(content);
    },
    [content, variant, colorSecondary]
  );

  var contentWithGradient = React.useMemo(
    function () {
      if (!shouldUseGradient) return contentWithSecondaryColor;

      // Replace currentColor with gradient reference
      var replaceCurrentColorWithGradient = (
        node: React.ReactNode
      ): React.ReactNode => {
        if (!React.isValidElement(node)) return node;

        var el = node as React.ReactElement;
        var elementProps: Record<string, unknown> = Object.assign({}, el.props);

        // Replace fill="currentColor" with gradient
        if (elementProps.fill === 'currentColor') {
          elementProps.fill = 'url(#' + gradientId + ')';
        }

        // Replace stroke="currentColor" with gradient
        if (elementProps.stroke === 'currentColor') {
          elementProps.stroke = 'url(#' + gradientId + ')';
        }

        var children = elementProps.children;
        if (children !== undefined && children !== null) {
          elementProps.children = React.Children.map(
            children as React.ReactElement,
            function (c: React.ReactElement) {
              return replaceCurrentColorWithGradient(c);
            }
          );
        }

        return React.cloneElement(el, elementProps);
      };

      return replaceCurrentColorWithGradient(contentWithSecondaryColor);
    },
    [contentWithSecondaryColor, shouldUseGradient, gradientId]
  );

  // Calculate expanded viewBox for shadow/glow
  var finalViewBox = item?.viewBox ?? '0 0 24 24';

  if (shadow && shadowBlur > 5) {
    // Parse viewBox to expand it
    var vbParts = finalViewBox.trim().split(/\\s+/).map(Number);
    if (vbParts.length === 4) {
      var vbX = vbParts[0];
      var vbY = vbParts[1];
      var vbW = vbParts[2];
      var vbH = vbParts[3];

      // Calculate expansion based on blur and offset
      var blurExpansion = shadowBlur * 3;
      var expandLeft = blurExpansion + Math.abs(Math.min(0, shadowOffsetX));
      var expandRight = blurExpansion + Math.max(0, shadowOffsetX);
      var expandTop = blurExpansion + Math.abs(Math.min(0, shadowOffsetY));
      var expandBottom = blurExpansion + Math.max(0, shadowOffsetY);

      finalViewBox = [
        vbX - expandLeft,
        vbY - expandTop,
        vbW + expandLeft + expandRight,
        vbH + expandTop + expandBottom
      ].join(" ");
    }
  }

  // Helper function to render gradient based on type
  var renderGradient = () => {
    if (!shouldUseGradient) return null;

    if (gradientType === 'linear') {
      return (
        <LinearGradient
          id={gradientId}
          x1={gradientDirection === 'horizontal' ? '0%' : '50%'}
          y1={gradientDirection === 'horizontal' ? '50%' : '0%'}
          x2={gradientDirection === 'horizontal' ? '100%' : '50%'}
          y2={gradientDirection === 'horizontal' ? '50%' : '100%'}
        >
          <Stop offset={offsetFirst} stopColor={colorFirst} />
          <Stop offset={offsetSecond} stopColor={colorSecond} />
        </LinearGradient>
      );
    }

    if (gradientType === 'radial') {
      return (
        <RadialGradient id={gradientId} cx='50%' cy='50%' r={gradientRadius + '%'}>
          <Stop offset={offsetFirst} stopColor={colorFirst} />
          <Stop offset={offsetSecond} stopColor={colorSecond} />
        </RadialGradient>
      );
    }

    if (gradientType === 'angular') {
      // Sweep/angular gradient approximation with rotation
      var rad = (gradientAngle * Math.PI) / 180;
      var cx = 50 + 30 * Math.cos(rad);
      var cy = 50 + 30 * Math.sin(rad);

      return (
        <RadialGradient id={gradientId} cx={cx + '%'} cy={cy + '%'} r='50%' fx='50%' fy='50%'>
          <Stop offset='0%' stopColor={colorFirst} />
          <Stop offset='12.5%' stopColor={colorSecond} />
          <Stop offset='25%' stopColor={colorFirst} />
          <Stop offset='37.5%' stopColor={colorSecond} />
          <Stop offset='50%' stopColor={colorFirst} />
          <Stop offset='62.5%' stopColor={colorSecond} />
          <Stop offset='75%' stopColor={colorFirst} />
          <Stop offset='87.5%' stopColor={colorSecond} />
          <Stop offset='100%' stopColor={colorFirst} />
        </RadialGradient>
      );
    }

    if (gradientType === 'diamond') {
      // Diamond/rhombus gradient with rotation
      var radD = (gradientAngle * Math.PI) / 180;
      var x1 = 50 + 50 * Math.cos(radD);
      var y1 = 50 + 50 * Math.sin(radD);
      var x2 = 50 - 50 * Math.cos(radD);
      var y2 = 50 - 50 * Math.sin(radD);

      return (
        <LinearGradient id={gradientId} x1={x1 + '%'} y1={y1 + '%'} x2={x2 + '%'} y2={y2 + '%'}>
          <Stop offset='0%' stopColor={colorFirst} />
          <Stop offset='25%' stopColor={colorSecond} />
          <Stop offset='50%' stopColor={colorFirst} />
          <Stop offset='75%' stopColor={colorSecond} />
          <Stop offset='100%' stopColor={colorFirst} />
        </LinearGradient>
      );
    }

    return null;
  };

  var preserveAspectRatio = fit === 'cover' ? 'xMidYMid slice' : 'xMidYMid meet';

  // Early return check after all hooks
  if (!item) return null;

  return (
    <Svg
      viewBox={finalViewBox}
      width={wOut}
      height={hOut}
      preserveAspectRatio={preserveAspectRatio}
      color={color}
      fill={color ?? 'currentColor'}
      {...props}
    >
      <Defs>
        {renderGradient()}
        {shadow && (
          <Filter id={shadowId} x="-150%" y="-150%" width="400%" height="400%">
            <FeGaussianBlur
              in="SourceAlpha"
              stdDeviation={shadowBlur}
              result="blur"
            />
            <FeOffset
              in="blur"
              dx={shadowOffsetX}
              dy={shadowOffsetY}
              result="offsetBlur"
            />
            <FeFlood
              floodColor={shadowColor}
              floodOpacity={shadowOpacity}
              result="color"
            />
            <FeComposite
              in="color"
              in2="offsetBlur"
              operator="in"
              result="shadow"
            />
            <FeMerge>
              <FeMergeNode in="shadow" />
              <FeMergeNode in="SourceGraphic" />
            </FeMerge>
          </Filter>
        )}
      </Defs>
      <G filter={shadow ? "url(#" + shadowId + ")" : undefined}>
        {contentWithGradient}
      </G>
    </Svg>
  );
};

export default Icon;
